// Usage notes — the learner's-dictionary layer (see the word_usage migration):
// grammar codes and patterns, inflected forms, CEFR and frequency, register
// labels, common mistakes, confusable words, how synonyms differ, phrasal
// verbs, syllables and origin.
//
// Generated by its own call rather than added to the main generation: that
// prompt is already near its token budget, every word cached before this
// existed would need it anyway, and the card can show the definition first and
// fill these in a moment later. Generated once per word, then shared.

import type { SupabaseClient } from 'npm:@supabase/supabase-js@2';
import { callProvider, stripFences, underRateLimit } from '../_shared/ai.ts';
import { keepAlive, type Svc } from './db.ts';
import { asUsage } from './sanitize.ts';
import type { CachedWord } from './cache.ts';
import type { Usage } from './types.ts';

/** The nothing-to-say value: same keys, empty values. */
export const EMPTY_USAGE: Usage = asUsage(null);

const SYSTEM = 'You are an editor of an English learner\'s dictionary (like Oxford Advanced Learner\'s or Cambridge). Return ONLY valid JSON, no markdown, no explanation.';

// deno-lint-ignore no-explicit-any
function fromRow(row: Record<string, any>): Usage {
  return asUsage({
    cefr: row.cefr,
    frequency: row.frequency,
    syllables: row.syllables,
    labels: row.labels,
    grammar: row.grammar,
    patterns: row.patterns,
    forms: row.forms,
    variants: row.variants,
    mistakes: row.mistakes,
    confusables: row.confusables,
    synonymNotes: row.synonym_notes,
    phrasalVerbs: row.phrasal_verbs,
    origin: row.origin,
  });
}

async function readUsage(svc: Svc, wordKey: string): Promise<Usage | null> {
  if (!svc) return null;
  const { data: row } = await svc.from('word_usage').select('*').eq('word', wordKey).maybeSingle();
  return row ? fromRow(row) : null;
}

function storeUsage(svc: Svc, wordKey: string, u: Usage): void {
  if (!svc) return;
  keepAlive(Promise.resolve(svc.from('word_usage').upsert({
    word: wordKey,
    cefr: u.cefr,
    frequency: u.frequency,
    syllables: u.syllables,
    labels: u.labels,
    grammar: u.grammar,
    patterns: u.patterns,
    forms: u.forms,
    variants: u.variants,
    mistakes: u.mistakes,
    confusables: u.confusables,
    synonym_notes: u.synonymNotes,
    phrasal_verbs: u.phrasalVerbs,
    origin: u.origin,
  })).then((res: { error: unknown }) => {
    if (res.error) console.warn('[word] usage write failed:', res.error);
  }));
}

async function generateUsage(word: string, pos: string | undefined, definition: string): Promise<Usage> {
  const prompt = `Write the learner's-dictionary notes for the English word "${word}"${pos ? ` (${pos})` : ''}, meaning: ${definition}

Return this exact JSON structure:
{
  "cefr": "A1 | A2 | B1 | B2 | C1 | C2 — the CEFR level at which learners typically learn this word, as in the English Vocabulary Profile",
  "frequency": 3,
  "syllables": "the word split into syllables with middle dots, e.g. \\"de·cide\\"",
  "labels": ["register or region labels that apply to the word itself, e.g. formal, informal, slang, offensive, old-fashioned, literary, technical, US, UK"],
  "grammar": ["grammar codes, e.g. countable, uncountable, plural only, transitive, intransitive, usually passive, not used in progressive"],
  "patterns": [{ "pattern": "a sentence pattern using sth / sb / to do sth / doing sth / that…, e.g. decide to do sth", "example": "a short natural example of exactly that pattern" }],
  "forms": [{ "label": "e.g. third person, past tense, past participle, -ing form, plural, comparative, superlative", "form": "the inflected form" }],
  "variants": [{ "region": "US or UK", "spelling": "the other region's spelling" }],
  "mistakes": [{ "wrong": "an incorrect sentence learners really write", "right": "the corrected sentence", "why": "one short reason" }],
  "confusables": [{ "word": "a word learners confuse with this one", "difference": "one short sentence on how they differ" }],
  "synonymNotes": [{ "word": "a close synonym", "difference": "one short sentence on when to use it instead" }],
  "phrasalVerbs": [{ "phrase": "a common phrasal verb built on this word", "meaning": "short meaning" }],
  "origin": "one short sentence on where the word comes from"
}

Rules:
- "frequency": 3 if it is among the ~3000 most common English words, 2 if common, 1 if less common.
- "labels": [] for an ordinary neutral word — do NOT add "neutral" or "standard".
- "patterns": 2-5 of the patterns a learner most needs; [] for words that don't take any (e.g. most concrete nouns).
- "forms": every inflected form for the word's part(s) of speech, including regular ones; [] if it doesn't inflect. Irregular forms matter most.
- "variants": [] unless US and UK spelling genuinely differ.
- "mistakes": 0-3 errors English learners commonly make with this word (wrong preposition, wrong pattern, false friend, wrong countability). Only real, frequent mistakes; [] if none.
- "confusables": 0-2 words learners genuinely mix up with this one (affect/effect, borrow/lend); [] if none.
- "synonymNotes": 0-4 synonyms, each with how it differs in meaning, strength or register.
- "phrasalVerbs": only for verbs — the most common phrasal verbs built on it, most common first, at most 8; [] otherwise.
- "origin": keep it to one sentence; null if unknown.
- Never invent: an empty list is always better than a made-up entry.`;

  const raw = await callProvider(SYSTEM, [{ role: 'user', content: prompt }], 1800);
  return asUsage(JSON.parse(stripFences(raw)));
}

/**
 * A word's usage notes: stored, or generated now and stored. Same rules as the
 * translation top-up in cache.ts — a visitor only gets what's already there, a
 * signed-in user's generation is rate-limited, and any failure is the empty
 * shape, since the card reads fine without it.
 */
export async function usageFor(svc: Svc, userClient: SupabaseClient | null, cached: CachedWord): Promise<Usage> {
  const stored = await readUsage(svc, cached.word);
  if (stored) return stored;
  if (!userClient || !svc) return EMPTY_USAGE;
  if (!await underRateLimit(userClient)) return EMPTY_USAGE;

  try {
    console.log(`[word] AI call: usage "${cached.word}"`);
    // The seed, not the headword: usage notes describe the English word.
    const usage = await generateUsage(cached.word, cached.data.partOfSpeech, String(cached.data.definition));
    storeUsage(svc, cached.word, usage);
    return usage;
  } catch (err) {
    console.warn(`[word] usage failed for "${cached.word}":`, (err as Error).message);
    return EMPTY_USAGE;
  }
}
